Section DT.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HHbp : asan_rt_hyps_bp H.
  Variable LINV : mem -> Prop.
  Hypothesis LINV_frame : forall m m' W, LINV m -> munch W m m' -> wmono asegs m m' ->
    Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) W -> LINV m'.
  Hypothesis LINV_cl : forall m m', LINV m -> (forall a, 0 <= a < 2 ^ 64 -> aimg_client a -> m' (wa a) = m (wa a)) -> LINV m'.
  Hypothesis HOWN : rt_own H.

  Definition shdrA (w : pmwA H) (m : mem) (sb : sbuf) : Prop :=
    match sb with
    | SShort => exists b0, rw_cells asegs m (wa_ff w + 6736) [C1 (b8 b0)] /\ 0 <= b0 < 256 /\ b0 mod 2 = 0
    | SLong d asz => exists b0 cp, rw_cells asegs m (wa_ff w + 6736) [C1 (b8 b0)] /\ 0 <= b0 < 256 /\ b0 mod 2 = 1
                     /\ rw_cells asegs m (wa_ff w + 6736) [C8 (Z_to_bv 64 cp)]
                     /\ rw_cells asegs m (wa_ff w + 6752) [C8 (Z_to_bv 64 d)] /\ 0 <= d < 2 ^ 64
    end.
  Lemma shdrA_keep : forall (w : pmwA H) m m' sb, shdrA w m sb -> ffkeep w m m' -> shdrA w m' sb.
